from openai import OpenAI

client = OpenAI(api_key="sk-aae514573e4a473294c19515791e3278", base_url="https://api.deepseek.com")

img = ("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJ"
       "AAAAC0lEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==")

for model in ["deepseek-chat", "deepseek-flash", "deepseek-v4-pro"]:
    msgs = [{
        "role": "user",
        "content": [
            {"type": "text", "text": "What do you see? one word."},
            {"type": "image_url", "image_url": {"url": img}},
        ],
    }]
    try:
        r = client.chat.completions.create(model=model, messages=msgs, max_tokens=10)
        print(f"{model}: VISION_OK ->", repr(r.choices[0].message.content))
    except Exception as e:
        print(f"{model}: FAIL ->", type(e).__name__, str(e)[:200])

